"""EXP-02: downloadable CSVs (08 §7.9.3).

* ``aggregate``: one row per month for a preset AOI, built from the EXP-01 bundle
  (``monthly_<aoi_id>.json`` + ``index.json``), with a ``#`` comment header.
* ``detections``: cleaned detection points (``derived/detections.parquet``) inside a lon/lat
  bbox and a local-date range, same comment header.

Columns that upstream modules do not produce yet are written empty (see README).

Usage::

    python -m pipeline.export.csv_export aggregate --aoi IDN [--bundle DIR] [--out FILE]
    python -m pipeline.export.csv_export detections --bbox LON_MIN LAT_MIN LON_MAX LAT_MAX \
        --start YYYY-MM-DD --end YYYY-MM-DD [--out FILE]
"""
from __future__ import annotations

import argparse
import csv
import datetime as dt
import json
import re
from pathlib import Path

import duckdb

from pipeline.data import config

APP = "Second Sight - harmonized MODIS/VIIRS fire activity for Indonesia"
# Placeholders to confirm against docs/datasheet.md (EXP-04) before release.
CITATION = ("NASA FIRMS (https://firms.modaps.eosdis.nasa.gov): MODIS Collection 6.1 active fire "
            "(MCD14ML, doi:10.5067/FIRMS/MODIS/MCD14ML) and VIIRS 375 m active fire "
            "(S-NPP, NOAA-20) standard-processing archive; processed by Second Sight.")
LICENSE = ("FIRMS data: NASA Earth science open data policy (attribution requested). "
           "Derived-table license: TBD, see repository datasheet.")
AI_NOTE = ("AI tools assisted in writing pipeline code; all numbers are computed by the "
           "open pipeline from FIRMS data, not generated by AI.")
FILTERS = "type=0; MODIS confidence>=30; VIIRS confidence nominal/high; static-source mask for NRT"

# 08 §7.9.3 column order + evidence_id
AGG_COLUMNS = [
    "aoi_id", "aoi_name", "year", "month",
    "terra_raw", "aqua_raw", "snpp_raw", "noaa20_raw",
    "sensor_used", "kappa", "kappa_lo", "kappa_hi",
    "H", "H_lo", "H_hi", "H_peat", "H_mineral", "H_day", "H_night",
    "large_fire_index",
    "baseline_median", "pct_rank", "anomaly_logratio", "robust_z",
    "enso_class", "analog_rank", "analog_n",
    "flag_nrt", "flag_missing_days", "flag_drift_era", "flag_high_cloud",
    "evidence_id",
]
# bundle field -> CSV column
FROM_BUNDLE = {"T_raw": "terra_raw", "A_raw": "aqua_raw", "V_raw": "snpp_raw",
               "N20_raw": "noaa20_raw", "sensor_used": "sensor_used", "H": "H", "H_lo": "H_lo",
               "H_hi": "H_hi", "baseline_median": "baseline_median", "pct_rank": "pct_rank",
               "flag_nrt": "flag_nrt"}

DET_COLUMNS = ["latitude", "longitude", "satellite", "sensor", "acq_ts_utc", "local_date",
               "lst_hour", "daynight", "frp", "scan", "track", "a_pix", "confidence_raw",
               "conf_class", "island_region", "is_peat", "province", "regency", "khg_id"]


def header_lines(index: dict, filters: str) -> list[str]:
    cal = index.get("calibration_window") or []
    base = index.get("baseline_period") or []
    lines = [
        f"app: {APP}",
        f"data_version: {index.get('data_version', 'unknown')}",
        f"bundle_generated_at: {index.get('generated_at', '')}",
        f"download_date: {dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')}",
        f"filters: {filters}",
        f"baseline: median per calendar month {'-'.join(map(str, base))}",
        f"calibration_window: {'-'.join(map(str, cal))} (Aqua-MODIS-equivalent reference scale)",
        f"harmonized: {str(bool(index.get('harmonized'))).lower()}"
        + ("" if index.get("harmonized") else
           " (H, intervals, baseline and pct_rank empty: harmonization not available in this export)"),
        "unit: fire cell-days (0.01 deg cell x local date x satellite x day/night)",
        f"citation: {CITATION}",
        f"license: {LICENSE}",
        f"ai_acknowledgement: {AI_NOTE}",
    ]
    return ["# " + s for s in lines]


def _fmt(v):
    if v is None:
        return ""
    if isinstance(v, bool):
        return "1" if v else "0"
    return v


def load_index(bundle: Path) -> dict:
    p = bundle / "index.json"
    return json.loads(p.read_text(encoding="utf-8")) if p.exists() else {}


def aggregate_rows(rows: list[dict], aoi_name: str, data_version: str) -> list[dict]:
    out = []
    for r in rows:
        o = dict.fromkeys(AGG_COLUMNS)
        o.update(aoi_id=r["aoi_id"], aoi_name=aoi_name, year=r["year"], month=r["month"])
        for src, dst in FROM_BUNDLE.items():
            o[dst] = r.get(src)
        o["flag_drift_era"] = r["year"] >= 2022
        o["evidence_id"] = f"{r['aoi_id']}:{r['year']}-{r['month']:02d}:{data_version[:12]}"
        out.append(o)
    return out


def write_aggregate(aoi_id: str, bundle: Path | None = None, out: Path | None = None) -> Path:
    bundle = Path(bundle or config.data_dir() / "bundle")
    index = load_index(bundle)
    meta = next((a for a in index.get("aois", []) if a["aoi_id"] == aoi_id), {"name": aoi_id})
    rows = json.loads((bundle / f"monthly_{aoi_id}.json").read_text(encoding="utf-8"))
    out = Path(out or bundle / "csv" / f"second_sight_{aoi_id}_monthly.csv")
    out.parent.mkdir(parents=True, exist_ok=True)
    with open(out, "w", newline="", encoding="utf-8") as f:
        f.write("\n".join(header_lines(index, FILTERS)) + "\n")
        w = csv.DictWriter(f, fieldnames=AGG_COLUMNS, lineterminator="\n")
        w.writeheader()
        for o in aggregate_rows(rows, meta.get("name", aoi_id), index.get("data_version", "unknown")):
            w.writerow({k: _fmt(v) for k, v in o.items()})
    return out


def write_detections(bbox: tuple[float, float, float, float], start: str, end: str,
                     out: Path, detections: Path | None = None, bundle: Path | None = None) -> int:
    """Write detection points in bbox (lon_min, lat_min, lon_max, lat_max) and [start, end]."""
    lon0, lat0, lon1, lat1 = map(float, bbox)
    d0, d1 = dt.date.fromisoformat(start), dt.date.fromisoformat(end)
    src = Path(detections or config.derived_dir() / "detections.parquet").as_posix()
    con = duckdb.connect()
    have = {r[0] for r in con.execute(f"DESCRIBE SELECT * FROM read_parquet('{src}')").fetchall()}
    cols = ", ".join(c if c in have else f"NULL AS {c}" for c in DET_COLUMNS)
    df = con.execute(
        f"""SELECT {cols} FROM read_parquet('{src}')
            WHERE longitude BETWEEN ? AND ? AND latitude BETWEEN ? AND ?
              AND local_date BETWEEN ? AND ?
            ORDER BY acq_ts_utc, latitude, longitude""",
        [lon0, lon1, lat0, lat1, d0, d1]).df()
    index = load_index(Path(bundle or config.data_dir() / "bundle"))
    flt = f"{FILTERS}; bbox lon {lon0}..{lon1} lat {lat0}..{lat1}; local_date {d0}..{d1}"
    out = Path(out)
    out.parent.mkdir(parents=True, exist_ok=True)
    with open(out, "w", newline="", encoding="utf-8") as f:
        f.write("\n".join(header_lines(index, flt)) + "\n")
        df.to_csv(f, index=False, lineterminator="\n")
    return len(df)


def restamp_data_version(bundle: Path) -> list[Path]:
    """Rewrite the data_version header of every bundle CSV from index.json (single source)."""
    version = load_index(Path(bundle)).get("data_version", "unknown")
    changed = []
    for f in sorted((Path(bundle) / "csv").glob("*.csv")):
        text = f.read_text(encoding="utf-8")
        new = re.sub(r"^# data_version: .*$", f"# data_version: {version}", text, count=1, flags=re.M)
        if new != text:
            f.write_text(new, encoding="utf-8", newline="")
            changed.append(f)
    return changed


def main(argv: list[str] | None = None) -> None:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    sub = ap.add_subparsers(dest="cmd", required=True)
    a = sub.add_parser("aggregate")
    a.add_argument("--aoi", default="all", help="aoi_id or 'all'")
    a.add_argument("--bundle", type=Path, default=None)
    a.add_argument("--out", type=Path, default=None)
    d = sub.add_parser("detections")
    d.add_argument("--bbox", type=float, nargs=4, required=True,
                   metavar=("LON_MIN", "LAT_MIN", "LON_MAX", "LAT_MAX"))
    d.add_argument("--start", required=True)
    d.add_argument("--end", required=True)
    d.add_argument("--out", type=Path, required=True)
    args = ap.parse_args(argv)
    if args.cmd == "aggregate":
        bundle = Path(args.bundle or config.data_dir() / "bundle")
        ids = ([x["aoi_id"] for x in load_index(bundle).get("aois", [])]
               if args.aoi == "all" else [args.aoi])
        for aid in ids:
            p = write_aggregate(aid, bundle, args.out if args.aoi != "all" else None)
            print(p, p.stat().st_size)
        restamp_data_version(bundle)
    else:
        n = write_detections(tuple(args.bbox), args.start, args.end, args.out)
        print(args.out, n, "rows")


if __name__ == "__main__":
    main()
